    await queryRunner.query(`ALTER TABLE user_credits RENAME TO subscriptions`)

    // ─── Rename RLS policies ────────────────────────────────────────────
    for (const op of ['select', 'insert', 'update', 'delete'] as const) {
      await queryRunner.query(`ALTER POLICY "user_credits_${op}" ON subscriptions RENAME TO "subscriptions_${op}"`)
    }

    // ─── Rename updated_at trigger ──────────────────────────────────────
    await queryRunner.query(`ALTER TRIGGER user_credits_updated_at ON subscriptions RENAME TO subscriptions_updated_at`)

